/** Conversions between the application models and the "customers" table: what the service takes and returns. */
object CustomerConversions {
    /** A Customer as the customers table takes it. */
    fun customerModelToCustomer(model: CustomerModel): Customer {
        return Customer(
            email = model.email,
            level = model.level?.let { when (it) { Level.basic -> "basic"; Level.gold -> "gold" } },
            since = model.since,
            address = customerAddressToDocument(model.address),
            tags = model.tags,
        )
    }

    /** A row of the customers table as a Customer. */
    fun customerToCustomerModel(row: Customer): CustomerModel {
        return CustomerModel(
            id = row.id!!,
            email = row.email!!,
            level = row.level?.let { when (it) { "basic" -> Level.basic; "gold" -> Level.gold; else -> throw IllegalArgumentException("No Level for this value") } },
            since = row.since!!,
            address = customerAddressFromDocument(row.address!!),
            tags = row.tags.orEmpty(),
        )
    }

    /** A Location as the documents of the customers collection keep it. */
    private fun customerAddressLocationToDocument(value: Location): Customer.Address.Location {
        return Customer.Address.Location(
            latitude = value.latitude,
            longitude = value.longitude,
        )
    }

    /** An Address as the documents of the customers collection keep it. */
    private fun customerAddressToDocument(value: Address): Customer.Address {
        return Customer.Address(
            street = value.street,
            zipCode = value.zipCode,
            location = value.location?.let { customerAddressLocationToDocument(it) },
        )
    }

    /** A document of the customers collection as a Location. */
    private fun customerAddressLocationFromDocument(value: Customer.Address.Location): Location {
        return Location(
            latitude = value.latitude!!,
            longitude = value.longitude!!,
        )
    }

    /** A document of the customers collection as an Address. */
    private fun customerAddressFromDocument(value: Customer.Address): Address {
        return Address(
            street = value.street!!,
            zipCode = value.zipCode!!,
            location = value.location?.let { customerAddressLocationFromDocument(it) },
        )
    }
}

