import app.application_models.Shipping
import app.entities.Order
import java.time.ZoneOffset

/** Conversions between the application models and the "orders" table: what the service takes and returns. */
object OrderConversions {
    /** An Order as the orders table takes it. */
    fun orderModelToOrder(model: OrderModel): Order {
        return Order(
            code = model.code,
            lines = model.lines.map { orderLinesToDocument(it) },
            shipping = model.shipping?.let { orderShippingToDocument(it) },
        )
    }

    /** A row of the orders table as an Order. */
    fun orderToOrderModel(row: Order): OrderModel {
        return OrderModel(
            id = row.id!!,
            code = row.code!!,
            lines = row.lines.orEmpty().map { orderLinesFromDocument(it) },
            shipping = row.shipping?.let { orderShippingFromDocument(it) },
        )
    }

    /** A Discount as the documents of the orders collection keep it. */
    private fun orderLinesDiscountsToDocument(value: Discount): Order.Line.Discount {
        return Order.Line.Discount(
            reason = value.reason,
            percent = value.percent,
        )
    }

    /** An OrderLine as the documents of the orders collection keep it. */
    private fun orderLinesToDocument(value: OrderLine): Order.Line {
        return Order.Line(
            id = value.id,
            sku = value.sku,
            quantity = value.quantity,
            price = value.price,
            status = value.status?.let { when (it) { LineStatus.pending -> "pending"; LineStatus.sent -> "sent" } },
            discounts = value.discounts.map { orderLinesDiscountsToDocument(it) },
        )
    }

    /** A Shipping as the documents of the orders collection keep it. */
    private fun orderShippingToDocument(value: Shipping): Order.Shipping {
        return Order.Shipping(
            carrier = value.carrier,
            sentOn = value.sentOn.atStartOfDay(ZoneOffset.UTC).toInstant(),
        )
    }

    /** A document of the orders collection as a Discount. */
    private fun orderLinesDiscountsFromDocument(value: Order.Line.Discount): Discount {
        return Discount().apply {
            reason = value.reason!!
            percent = value.percent!!
        }
    }

    /** A document of the orders collection as an OrderLine. */
    private fun orderLinesFromDocument(value: Order.Line): OrderLine {
        return OrderLine().apply {
            id = value.id
            sku = value.sku!!
            quantity = value.quantity!!
            price = value.price!!
            status = value.status?.let { when (it) { "pending" -> LineStatus.pending; "sent" -> LineStatus.sent; else -> throw IllegalArgumentException("No LineStatus for this value") } }
            discounts = value.discounts.orEmpty().map { orderLinesDiscountsFromDocument(it) }
        }
    }

    /** A document of the orders collection as a Shipping. */
    private fun orderShippingFromDocument(value: Order.Shipping): Shipping {
        return Shipping(
            carrier = value.carrier!!,
            sentOn = value.sentOn!!.atOffset(ZoneOffset.UTC).toLocalDate(),
        )
    }
}

