package app.repositories

import app.common.Page
import app.entities.Customer
import org.bson.types.ObjectId

/** Keeps customers rows in memory, for tests and for trying the services without a database. */
class MemoryCustomerRepository : CustomerRepository {
    private val rows = linkedMapOf<List<Any?>, Customer>()

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: Customer): List<Any?> = listOf(row.id)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<Customer> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun findById(id: String): Customer? {
        return visible().firstOrNull { it.id == id }
    }

    override fun list(offset: Int, limit: Int): Page<Customer> {
        val rows = visible()
        return Page(rows.drop(offset).take(limit), rows.size.toLong(), offset, limit)
    }

    override fun findByEmail(email: String): Customer? {
        return visible().firstOrNull { it.email == email }
    }

    override fun insert(entity: Customer): Customer {
        entity.id = entity.id ?: ObjectId().toHexString()
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun update(entity: Customer): Customer {
        rows[keyOf(entity)] = entity
        return entity
    }

    override fun delete(entity: Customer): Unit {
        rows.remove(keyOf(entity))
    }

    override fun addTag(id: String, tag: String): Customer? {
        val found = visible().firstOrNull { it.id == id } ?: return null
        found.tags = found.tags.orEmpty() + listOf(tag)
        return found
    }

    override fun removeTag(id: String, tag: String): Customer? {
        val found = visible().firstOrNull { it.id == id } ?: return null
        found.tags = found.tags.orEmpty().filter { it != tag }
        return found
    }
}

