package app.repositories

import app.Db
import app.Documents
import app.common.Page
import app.entities.Shipment
import java.util.Collections
import java.util.WeakHashMap
import org.bson.Document
import org.bson.types.ObjectId

/** Keeps shipments rows in the database, through the MongoDB driver. Every write is stored at once. */
class MongoShipmentRepository(private val db: Db) : ShipmentRepository {
    private val collection = "shipments"

    /** The fields a change may write */
    private val fields = listOf("parcel", "stops")

    override fun findById(id: String): Shipment? {
        if (!ObjectId.isValid(id)) return null
        return db.find(collection, Document("_id", ObjectId(id)), limit = 1).firstOrNull()?.let { loaded(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Shipment> {
        val items = if (limit > 0) db.find(collection, Document(), sort = Document("_id", 1), skip = offset, limit = limit).map { loaded(it) } else emptyList()
        return Page(items, db.count(collection, Document()), offset, limit)
    }

    override fun insert(entity: Shipment): Shipment {
        entity.id = entity.id ?: ObjectId().toHexString()
        db.insert("Shipment", collection, toDocument(entity))
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    override fun update(entity: Shipment): Shipment {
        val now = toDocument(entity)
        val changes = Documents.changes(READ[entity], now, fields)
        if (changes.isNotEmpty()) {
            db.update("Shipment", collection, Document("_id", now["_id"]), changes)
        }
        READ[entity] = Documents.copy(now) as Document
        return entity
    }

    override fun delete(entity: Shipment): Unit {
        db.delete("Shipment", collection, Document("_id", ObjectId(entity.id!!)))
    }

    override fun addStop(id: String, stop: Shipment.Stop): Shipment? {
        if (!ObjectId.isValid(id)) return null
        val change = Document("\$push", Document("stops", stopToDocument(stop)))
        return db.change("Shipment", collection, Document("_id", ObjectId(id)), change)?.let { loaded(it) }
    }

    override fun removeStop(id: String, position: Int, size: Int): Shipment? {
        if (!ObjectId.isValid(id)) return null
        val head = Document("\$slice", listOf("\$stops", position))
        val tail = Document("\$slice", listOf("\$stops", position + 1, maxOf(size, 1)))
        val change = listOf(Document("\$set", Document("stops", Document("\$concatArrays", listOf(head, tail)))))
        return db.rewrite("Shipment", collection, Document("_id", ObjectId(id)).append("stops", Document("\$size", size)), change)?.let { loaded(it) }
    }

    /** The entity of a document, with the document kept to tell its changes. */
    private fun loaded(document: Document): Shipment {
        val entity = fromDocument(document)
        READ[entity] = Documents.copy(toDocument(entity)) as Document
        return entity
    }

    /** The document of a Shipment: what is null is left out. */
    private fun toDocument(value: Shipment): Document {
        val document = Document()
        value.id?.let { document["_id"] = ObjectId(it) }
        value.parcel?.let { document["parcel"] = parcelToDocument(it) }
        value.stops?.let { held -> document["stops"] = held.map { stopToDocument(it) } }
        return document
    }

    private fun fromDocument(document: Document): Shipment =
        Shipment(
            id = document["_id"]?.toString(),
            parcel = (document["parcel"] as Document?)?.let { parcelFromDocument(it) },
            stops = (document["stops"] as List<*>?)?.mapNotNull { (it as Document?)?.let { stopFromDocument(it) } },
        )

    /** The document of a Shipment.Parcel: what is null is left out. */
    private fun parcelToDocument(value: Shipment.Parcel): Document {
        val document = Document()
        value.weight?.let { document["weight"] = it }
        value.contents?.let { document["contents"] = it }
        value.size?.let { document["size"] = parcelSizeToDocument(it) }
        return document
    }

    private fun parcelFromDocument(document: Document): Shipment.Parcel =
        Shipment.Parcel(
            weight = (document["weight"] as Number?)?.toDouble(),
            contents = document["contents"] as String?,
            size = (document["size"] as Document?)?.let { parcelSizeFromDocument(it) },
        )

    /** The document of a Shipment.Parcel.Size: what is null is left out. */
    private fun parcelSizeToDocument(value: Shipment.Parcel.Size): Document {
        val document = Document()
        value.height?.let { document["height"] = it }
        return document
    }

    private fun parcelSizeFromDocument(document: Document): Shipment.Parcel.Size =
        Shipment.Parcel.Size(
            height = (document["height"] as Number?)?.toDouble(),
        )

    /** The document of a Shipment.Stop: what is null is left out. */
    private fun stopToDocument(value: Shipment.Stop): Document {
        val document = Document()
        value.city?.let { document["city"] = it }
        return document
    }

    private fun stopFromDocument(document: Document): Shipment.Stop =
        Shipment.Stop(
            city = document["city"] as String?,
        )

    private companion object {
        /** The document each entity was read from: a change writes only the fields that differ */
        val READ: MutableMap<Shipment, Document> = Collections.synchronizedMap(WeakHashMap())
    }
}

