package app.services

import app.UnitOfWork
import app.common.Page
import app.entities.Order
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on orders. Repositories commit every write. */
@Suppress("UNCHECKED_CAST")
class OrderService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Order after checking it. */
    fun createOrder(order: Order): Order {
        val values = mapOf(
            "code" to order.code,
            "lines" to order.lines,
            "shipping" to order.shipping,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.orders.insert(order)
        }
    }

    /** The Order with this key; NotFoundException when there is none. */
    fun getOrder(id: String): Order = find(unitOfWork, id)

    /** A page of orders, by primary key. */
    fun listOrders(offset: Int, limit: Int): Page<Order> = unitOfWork.orders.list(offset, limit)

    /** Changes the given values of a Order. */
    fun updateOrder(id: String, changes: OrderChanges): Order {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.orders.update(current)
        }
    }

    /** Deletes a Order. */
    fun deleteOrder(id: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.orders.delete(current)
        }
    }

    /** The Order with this code, or null. */
    fun findOrderByCode(code: String): Order? = unitOfWork.orders.findByCode(code)

    /** Adds an item to lines. */
    fun addLine(id: String, line: Order.Line): Order {
        val errors = mutableListOf<FieldError>()
        checkLine(line, "lines", errors)
        if (errors.isNotEmpty()) throw ValidationFailedException("Order", errors)
        return unitOfWork.transaction { uow ->
            find(uow, id)
            uow.orders.addLine(id, line) ?: throw NotFoundException("Order", id)
        }
    }

    /** Removes an item from lines, by its identifier. */
    fun removeLine(id: String, lineId: String): Order {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.lines.orEmpty().none { it.id == lineId }) throw NotFoundException("Line", lineId)
            uow.orders.removeLine(id, lineId) ?: throw NotFoundException("Order", id)
        }
    }

    /** Checks the values against the rules of the "orders" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Order?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["code"]
            if (value == null) {
                if (creating || "code" in values) errors += FieldError("code", "is required")
            }
        }
        run {
            val value = values["lines"]
            if (value == null) {
                if (creating || "lines" in values) errors += FieldError("lines", "is required")
            } else {
                val document = value as List<Order.Line>
                document.forEachIndexed { i0, item0 ->
                    checkLine(item0, "lines" + "." + i0, errors)
                }
            }
        }
        run {
            val value = values["shipping"]
            if (value != null) {
                val document = value as Order.Shipping
                checkShipping(document, "shipping", errors)
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Order", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Order?) {
        run {
            val code = if ("code" in values) values["code"] as String? else current?.code
            if (code != null) {
                val other = uow.orders.findByCode(code)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Order", "code is already taken", listOf("code"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Order?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Order, values: Map<String, Any?>) {
        if ("code" in values) entity.code = values["code"] as String?
        if ("lines" in values) entity.lines = values["lines"] as List<Order.Line>?
        if ("shipping" in values) entity.shipping = values["shipping"] as Order.Shipping?
    }

    /** The Order with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): Order =
        uow.orders.findById(id) ?: throw NotFoundException("Order", id)

    /** The values an update gives, by field. */
    private fun given(changes: OrderChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.code.isPresent) values["code"] = changes.code.value
        if (changes.lines.isPresent) values["lines"] = changes.lines.value
        if (changes.shipping.isPresent) values["shipping"] = changes.shipping.value
        return values
    }

    /** What a Order.Line does not follow of its rules, each with the path of its field. */
    private fun checkLine(value: Order.Line, path: String, errors: MutableList<FieldError>) {
        if (value.sku == null) errors += FieldError(path + ".sku", "is required")
        if (value.quantity == null) errors += FieldError(path + ".quantity", "is required")
        if (value.price == null) errors += FieldError(path + ".price", "is required")
        value.status.let { held ->
            if (held != null) {
                if (held !in listOf("pending", "sent")) errors += FieldError(path + ".status", "must be one of: pending, sent")
            }
        }
        value.discounts.let { held ->
            if (held != null) {
                held.forEachIndexed { i0, item0 ->
                    checkLineDiscount(item0, path + ".discounts" + "." + i0, errors)
                }
            }
        }
    }

    /** What a Order.Line.Discount does not follow of its rules, each with the path of its field. */
    private fun checkLineDiscount(value: Order.Line.Discount, path: String, errors: MutableList<FieldError>) {
        if (value.reason == null) errors += FieldError(path + ".reason", "is required")
        if (value.percent == null) errors += FieldError(path + ".percent", "is required")
    }

    /** What a Order.Shipping does not follow of its rules, each with the path of its field. */
    private fun checkShipping(value: Order.Shipping, path: String, errors: MutableList<FieldError>) {
        if (value.carrier == null) errors += FieldError(path + ".carrier", "is required")
        if (value.sentOn == null) errors += FieldError(path + ".sentOn", "is required")
