package app.services

import app.UnitOfWork
import app.common.Page
import app.entities.Shipment
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on shipments. Repositories commit every write. */
@Suppress("UNCHECKED_CAST")
class ShipmentService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Shipment after checking it. */
    fun createShipment(shipment: Shipment): Shipment {
        val values = mapOf(
            "parcel" to shipment.parcel,
            "stops" to shipment.stops,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.shipments.insert(shipment)
        }
    }

    /** The Shipment with this key; NotFoundException when there is none. */
    fun getShipment(id: String): Shipment = find(unitOfWork, id)

    /** A page of shipments, by primary key. */
    fun listShipments(offset: Int, limit: Int): Page<Shipment> = unitOfWork.shipments.list(offset, limit)

    /** Changes the given values of a Shipment. */
    fun updateShipment(id: String, changes: ShipmentChanges): Shipment {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.shipments.update(current)
        }
    }

    /** Deletes a Shipment. */
    fun deleteShipment(id: String) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.shipments.delete(current)
        }
    }

    /** Adds an item to stops. */
    fun addStop(id: String, stop: Shipment.Stop): Shipment {
        val errors = mutableListOf<FieldError>()
        checkStop(stop, "stops", errors)
        if (errors.isNotEmpty()) throw ValidationFailedException("Shipment", errors)
        return unitOfWork.transaction { uow ->
            find(uow, id)
            uow.shipments.addStop(id, stop) ?: throw NotFoundException("Shipment", id)
        }
    }

    /** Removes an item from stops, by its position. */
    fun removeStop(id: String, position: Int): Shipment {
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (position !in current.stops.orEmpty().indices) throw NotFoundException("Stop", position)
            uow.shipments.removeStop(id, position, current.stops.orEmpty().size) ?: throw ConflictException("Shipment", "was changed by someone else since it was read", listOf("stops"))
        }
    }

    /** Checks the values against the rules of the "shipments" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Shipment?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["parcel"]
            if (value == null) {
                if (creating || "parcel" in values) errors += FieldError("parcel", "is required")
            } else {
                val document = value as Shipment.Parcel
                checkParcel(document, "parcel", errors)
            }
        }
        run {
            val value = values["stops"]
            if (value != null) {
                val document = value as List<Shipment.Stop>
                document.forEachIndexed { i0, item0 ->
                    checkStop(item0, "stops" + "." + i0, errors)
                }
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Shipment", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Shipment?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Shipment, values: Map<String, Any?>) {
        if ("parcel" in values) entity.parcel = values["parcel"] as Shipment.Parcel?
        if ("stops" in values) entity.stops = values["stops"] as List<Shipment.Stop>?
    }

    /** The Shipment with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: String): Shipment =
        uow.shipments.findById(id) ?: throw NotFoundException("Shipment", id)

    /** The values an update gives, by field. */
    private fun given(changes: ShipmentChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.parcel.isPresent) values["parcel"] = changes.parcel.value
        if (changes.stops.isPresent) values["stops"] = changes.stops.value
        return values
    }

    /** What a Shipment.Parcel does not follow of its rules, each with the path of its field. */
    private fun checkParcel(value: Shipment.Parcel, path: String, errors: MutableList<FieldError>) {
        if (value.weight == null) errors += FieldError(path + ".weight", "is required")
        if (value.contents == null) errors += FieldError(path + ".contents", "is required")
        value.size.let { held ->
            if (held != null) {
                checkParcelSize(held, path + ".size", errors)
            }
        }
    }

    /** What a Shipment.Parcel.Size does not follow of its rules, each with the path of its field. */
    private fun checkParcelSize(value: Shipment.Parcel.Size, path: String, errors: MutableList<FieldError>) {
        if (value.height == null) errors += FieldError(path + ".height", "is required")
    }

    /** What a Shipment.Stop does not follow of its rules, each with the path of its field. */
    @Suppress("UNUSED_PARAMETER")
    private fun checkStop(value: Shipment.Stop, path: String, errors: MutableList<FieldError>) {
    }
}

