        return uow.customers.insert(entity)
    }

    /** A valid Customer.Address; n makes its values differ. */
    fun newCustomerAddress(n: Int): Customer.Address =
        Customer.Address(
            street = "street-$n",
            zipCode = "zipcode-$n",
            location = newCustomerAddressLocation(n),
        )

    /** A valid Customer.Address.Location; n makes its values differ. */
    fun newCustomerAddressLocation(n: Int): Customer.Address.Location =
        Customer.Address.Location(
            latitude = n + 0.5,
            longitude = n + 0.5,
        )

    /** A valid Order that is not stored yet; n makes its unique values differ. */
    fun newOrder(n: Int): Order =
