            code = "code-$n",
            lines = listOf(newOrderLine(n)),
            shipping = newOrderShipping(n),
        )

    /** A stored Order. */
    fun addOrder(uow: UnitOfWork, n: Int): Order {
        val entity = newOrder(n)
        return uow.orders.insert(entity)
    }

    /** A valid Order.Line; n makes its values differ. */
    fun newOrderLine(n: Int): Order.Line =
        Order.Line(
            sku = "sku-$n",
            quantity = n,
            price = BigDecimal("${n % 10000}.50"),
            status = "pending",
            discounts = listOf(newOrderLineDiscount(n)),
        )

    /** A valid Order.Line.Discount; n makes its values differ. */
    fun newOrderLineDiscount(n: Int): Order.Line.Discount =
        Order.Line.Discount(
            reason = "reason-$n",
            percent = n + 0.5,
        )

    /** A valid Order.Shipping; n makes its values differ. */
    fun newOrderShipping(n: Int): Order.Shipping =
        Order.Shipping(
            carrier = "carrier-$n",
            sentOn = LocalDateTime.of(2026, 1, n % 28 + 1, 12, 0).toInstant(ZoneOffset.UTC),
        )

    /** A valid Shipment that is not stored yet; n makes its unique values differ. */
    fun newShipment(n: Int): Shipment =
        Shipment(
            parcel = newShipmentParcel(n),
