    }

    /** A valid Shipment.Parcel; n makes its values differ. */
    fun newShipmentParcel(n: Int): Shipment.Parcel =
        Shipment.Parcel(
            weight = n + 0.5,
            contents = "contents-$n",
            size = newShipmentParcelSize(n),
        )

    /** A valid Shipment.Parcel.Size; n makes its values differ. */
